import numpy as np
from collections import deque
F=np.load('source_pixels.npz')['rgb'].astype(int)

def comps(mask,minn=3):
 H,W=mask.shape; seen=np.zeros_like(mask,bool); out=[]
 for y,x in zip(*np.where(mask)):
  if seen[y,x]:continue
  st=[(y,x)];seen[y,x]=1; pts=[]
  while st:
   yy,xx=st.pop();pts.append((yy,xx))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     y2,x2=yy+dy,xx+dx
     if 0<=y2<H and 0<=x2<W and not seen[y2,x2] and mask[y2,x2]:seen[y2,x2]=1;st.append((y2,x2))
  if len(pts)>=minn:
   p=np.array(pts);out.append((len(pts),(p[:,1].min(),p[:,0].min(),p[:,1].max(),p[:,0].max()),(p[:,1].mean(),p[:,0].mean())))
 return sorted(out,reverse=True)

for refmode in ['prev','zero']:
